 export function buildHelpers(source, safe) {
   if (!source || !source.trim()) return { ok: true, helpers: {}, error: "" };
   const helpers = Object.create(null);
-  // `registerHelper(name, fn)` or `registerHelper(name, fn, arity)` (ADR-018),
-  // where `arity` is a number (exactly N), `[min, max]` (max null/Infinity ⇒
-  // at-least), or omitted (any). A declared arity gives the helper the same
-  // arity diagnostics as a built-in.
+  // `register(name, fn)` or `register(name, fn, arity)` (ADR-018), where `arity`
+  // is a number (exactly N), `[min, max]` (max null/Infinity ⇒ at-least), or
+  // omitted (any). A declared arity gives the operation the same arity
+  // diagnostics as a built-in.
   const register = (name, fn, arity) => {
-    if (typeof name !== "string" || !name) throw new Error("registerHelper(name, fn): name must be a non-empty string");
-    if (typeof fn !== "function") throw new Error("registerHelper('" + name + "', fn): fn must be a function");
+    if (typeof name !== "string" || !name) throw new Error("register(name, fn): name must be a non-empty string");
+    if (typeof fn !== "function") throw new Error("register('" + name + "', fn): fn must be a function");
     helpers[name] = arity === undefined ? fn : { fn, arity };
   };
   try {
-    // `registerHelper` + `safe` are the only names injected; the source runs
-    // for its side effects (registering helpers).
+    // `registerHelper` (FullBars) and `registerOperation` (native RawBars/MaxBars)
+    // are dialect-scoped aliases of the one `register` above — both fill the same
+    // bag, so a card teaches its dialect's word while every card stays runnable
+    // (ADR-019 addendum). `safe` is the third injected name; the source runs for
+    // its side effects (registering operations).
     // eslint-disable-next-line no-new-func
-    const run = new Function("registerHelper", "safe", source);
-    run(register, safe);
+    const run = new Function("registerHelper", "registerOperation", "safe", source);
+    run(register, register, safe);
     return { ok: true, helpers, error: "" };
   } catch (e) {
     return { ok: false, helpers: {}, error: String((e && e.message) || e) };

@@ -18,6 +18,25 @@ test("buildHelpers collects registerHelper calls into a bag", () => {
   assert.equal(r.helpers.loud("hi"), "HI");
 });

+test("registerOperation is the native alias of registerHelper — same bag (ADR-019)", () => {
+  // The two dialect-scoped names (FullBars `registerHelper`, native
+  // `registerOperation`) fill an identical bag, so a MaxBars/RawBars card can
+  // teach the native word and still run. Pins Nadia's "the two are identical".
+  const viaHelper = buildHelpers("registerHelper('loud', (s) => String(s).toUpperCase(), 1)", safe);
+  const viaOp = buildHelpers("registerOperation('loud', (s) => String(s).toUpperCase(), 1)", safe);
+  assert.equal(viaOp.ok, true);
+  assert.deepEqual(Object.keys(viaOp.helpers), Object.keys(viaHelper.helpers));
+  assert.equal(viaOp.helpers.loud.arity, viaHelper.helpers.loud.arity);
+  // both render identically through the native MaxBars entry point
+  assert.equal(renderMaxWith(viaOp.helpers, {}, "{{loud x}}", { x: "a" }).value, "A");
+  // and a single source may mix the two names freely
+  const mixed = buildHelpers(
+    "registerOperation('a', () => 'A');\nregisterHelper('b', () => 'B')",
+    safe,
+  );
+  assert.deepEqual(Object.keys(mixed.helpers).sort(), ["a", "b"]);
+});
+
 test("empty source is a valid empty bag", () => {
   assert.deepEqual(buildHelpers("", safe), { ok: true, helpers: {}, error: "" });
   assert.deepEqual(buildHelpers("   \n", safe).helpers, {});

